final class SchoolAssessments {
 public const TYPES=['quiz','assignment','monthly','exam','practical'];
 public function __construct(public ExamAccess $exam){}
 public function setup(Request $r):array{[$sid,$m]=$this->exam->context($r);$sections=$this->exam->sections($r)->orderByDesc('y.starts_on')->orderBy('c.position')->get();$offerings=DB::table('section_subjects as o')->join('subjects as s','s.id','=','o.subject_id')->where('o.school_id',$sid)->whereIn('o.section_id',$sections->pluck('id'))->get(['o.section_id','s.id as subject_id','s.name','s.code']);$assignments=$this->exam->assignments($m)->get(['a.section_id','a.subject_id','a.is_class_teacher']);foreach($offerings as $o)$o->can_write=$this->exam->can($r,'tests.enter_marks')&&($this->exam->can($r,'tests.publish')||$assignments->contains(fn($a)=>$a->section_id===$o->section_id&&$a->subject_id===$o->subject_id));return ['today'=>now('Asia/Karachi')->toDateString(),'can_publish'=>$this->exam->can($r,'tests.publish'),'sections'=>$sections,'offerings'=>$offerings,'schemes'=>DB::table('grading_schemes')->where('school_id',$sid)->orderByDesc('id')->get(),'cycles'=>DB::table('exam_cycles')->where('school_id',$sid)->whereIn('academic_session_id',$sections->pluck('academic_session_id'))->orderByDesc('starts_on')->get(),'terms'=>DB::table('academic_terms')->where('school_id',$sid)->whereIn('academic_session_id',$sections->pluck('academic_session_id'))->get(),'types'=>self::TYPES];}
 public function gradeScheme(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->exam->lock($r);abort_unless($this->exam->can($r,'tests.publish'),403);$bands=$d['bands'];foreach($bands as &$b){$b['min_percent']=$this->exam->number($this->exam->cents($b['min_percent']));if((float)$b['min_percent']>100)$this->exam->fail('Grade thresholds must be between zero and 100.');}unset($b);usort($bands,fn($a,$b)=>(float)$b['min_percent']<=>(float)$a['min_percent']);if(count(array_unique(array_column($bands,'min_percent')))!==count($bands)||end($bands)['min_percent']!=='0.00')$this->exam->fail('Grade thresholds must be unique and include a zero-percent band.');$version=(int)DB::table('grading_schemes')->where('school_id',$sid)->where('name',$d['name'])->max('version')+1;$id=DB::table('grading_schemes')->insertGetId(['school_id'=>$sid,'name'=>$d['name'],'version'=>$version,'rules'=>json_encode(['bands'=>$bands,'passing_percent'=>$d['passing_percent']]),'rounding_policy'=>$d['rounding_policy'],'tie_policy'=>$d['tie_policy'],'created_at'=>now(),'updated_at'=>now()]);$this->exam->access->audit($r,'exams.grading_created','grading_schemes',$id,['version'=>$version,'rules'=>$bands]);return ['id'=>$id,'message'=>'Grading scheme version created.'];});}
 public function cycle(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->exam->lock($r);abort_unless($this->exam->can($r,'tests.publish'),403);$s=$this->exam->section($r,$d['section_id']);$this->exam->active($s);$this->exam->scheme($sid,$d['grading_scheme_id']);if($d['starts_on']<$s->session_start||$d['ends_on']>$s->session_end)$this->exam->fail('Exam dates must fit the academic session.');if(!empty($d['academic_term_id'])){$term=DB::table('academic_terms')->where('school_id',$sid)->where('academic_session_id',$s->academic_session_id)->where('id',$d['academic_term_id'])->first()??abort(404);if($d['starts_on']<$term->starts_on||$d['ends_on']>$term->ends_on)$this->exam->fail('Exam dates must fit the selected term.');}$id=DB::table('exam_cycles')->insertGetId(['school_id'=>$sid,'academic_session_id'=>$s->academic_session_id,'academic_term_id'=>$d['academic_term_id']??null,'name'=>$d['name'],'starts_on'=>$d['starts_on'],'ends_on'=>$d['ends_on'],'grading_scheme_id'=>$d['grading_scheme_id'],'status'=>'active','created_at'=>now(),'updated_at'=>now()]);$this->exam->access->audit($r,'exams.cycle_created','exam_cycles',$id,$d);return ['id'=>$id,'message'=>'Exam cycle created.'];});}
 public function weights(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->exam->lock($r);abort_unless($this->exam->can($r,'tests.publish'),403);$s=$this->exam->section($r,$d['section_id']);$this->exam->active($s);$this->exam->subject($r,$s,$d['subject_id']);$cycle=DB::table('exam_cycles')->where('school_id',$sid)->where('id',$d['exam_cycle_id'])->where('academic_session_id',$s->academic_session_id)->first()??abort(404);if($cycle->lock_version!=$d['lock_version'])$this->exam->fail('Exam setup changed. Reload before saving weightages.');if(DB::table('consolidated_result_snapshots')->where('school_id',$sid)->where('exam_cycle_id',$cycle->id)->exists())$this->exam->fail('Published exam weightages are frozen. Create a new cycle for a different assessment policy.');$sum=0;foreach($d['weights'] as $row)$sum+=$this->exam->cents($row['weight']);if($sum!==10000)$this->exam->fail('Assessment weightages must total exactly 100%.');DB::table('assessment_weightages')->where('school_id',$sid)->where('exam_cycle_id',$cycle->id)->where('class_id',$s->class_id)->where('subject_id',$d['subject_id'])->delete();foreach($d['weights'] as $row)DB::table('assessment_weightages')->insert(['school_id'=>$sid,'exam_cycle_id'=>$cycle->id,'class_id'=>$s->class_id,'subject_id'=>$d['subject_id'],'assessment_type'=>$row['assessment_type'],'weight'=>$row['weight'],'created_at'=>now(),'updated_at'=>now()]);DB::table('exam_cycles')->where('id',$cycle->id)->update(['lock_version'=>$cycle->lock_version+1,'updated_at'=>now()]);$this->exam->access->audit($r,'exams.weightages_saved','exam_cycles',$cycle->id,$d);return ['message'=>'Weightages saved.'];});}
 public function createTest(Request $r,array $d,?int $id=null):array{return DB::transaction(function()use($r,$d,$id){$sid=$this->exam->lock($r);$s=$this->exam->section($r,$d['section_id']);$this->exam->active($s);$this->exam->subject($r,$s,$d['subject_id'],true);$this->exam->scheme($sid,$d['grading_scheme_id']);if($d['test_date']<$s->session_start||$d['test_date']>$s->session_end)$this->exam->fail('Test date must fit the academic session.');$max=$this->exam->cents($d['max_marks']);$pass=$this->exam->cents($d['passing_marks']);if(!$max||$pass>$max)$this->exam->fail('Maximum marks must be positive; passing marks cannot exceed them.');if(!empty($d['exam_cycle_id'])){$c=DB::table('exam_cycles')->where('school_id',$sid)->where('id',$d['exam_cycle_id'])->where('academic_session_id',$s->academic_session_id)->first()??abort(404);if($c->grading_scheme_id!=$d['grading_scheme_id']||$d['test_date']<$c->starts_on||$d['test_date']>$c->ends_on)$this->exam->fail('The test must use its cycle grading scheme and fit its dates.');if(!$id&&DB::table('consolidated_result_snapshots')->where('school_id',$sid)->where('exam_cycle_id',$c->id)->exists())$this->exam->fail('This cycle already has published cards. Correct existing papers or create a new cycle.');}
  $values=array_intersect_key($d,array_flip(['section_id','subject_id','exam_cycle_id','grading_scheme_id','title','test_date','max_marks','passing_marks','assessment_type']));$values['exam_cycle_id']=$d['exam_cycle_id']??null;$values['updated_at']=now();if($id){[$old]=$this->exam->test($r,$id,true);if($old->status!=='draft'||$old->lock_version!=$d['lock_version'])$this->exam->fail('Reload a draft test before editing its setup.');foreach(['section_id','subject_id','exam_cycle_id','grading_scheme_id','test_date','assessment_type'] as $key)if(($old->$key??null)!=($values[$key]??null))$this->exam->fail('Section, subject, date, cycle, type and grading version are fixed. Create another test for a different assessment.');if(DB::table('test_results')->where('school_id',$sid)->where('test_id',$id)->where('marks','>',$d['max_marks'])->exists())$this->exam->fail('Saved marks exceed the new maximum. Correct the marks first.');$values['lock_version']=$old->lock_version+1;DB::table('tests')->where('school_id',$sid)->where('id',$id)->update($values);}else{$id=DB::table('tests')->insertGetId($values+['school_id'=>$sid,'status'=>'draft','created_at'=>now()]);}
  $warnings=[];if(!empty($d['paper'])){$p=$d['paper'];$overlap=DB::table('exam_papers as p')->join('tests as t','t.id','=','p.test_id')->join('sections as s','s.id','=','t.section_id')->where('p.school_id',$sid)->where('p.test_id','<>',$id)->where('p.scheduled_on',$d['test_date'])->where('p.starts_at','<',$p['ends_at'])->where('p.ends_at','>',$p['starts_at'])->where('s.campus_id',$s->campus_id)->where(fn($q)=>$q->where('t.section_id',$s->id)->when(!empty($p['room']),fn($q)=>$q->orWhere('p.room',$p['room'])))->exists();if($overlap)$warnings[]='Date-sheet overlap: another paper uses this section or room at the same time. Review the schedule.';DB::table('exam_papers')->updateOrInsert(['school_id'=>$sid,'test_id'=>$id],['scheduled_on'=>$d['test_date'],'starts_at'=>$p['starts_at'],'ends_at'=>$p['ends_at'],'room'=>$p['room']??null,'updated_at'=>now()]);}elseif(array_key_exists('paper',$d))DB::table('exam_papers')->where('school_id',$sid)->where('test_id',$id)->delete();$this->exam->access->audit($r,'exams.test_setup_saved','tests',$id,$values+['warnings'=>$warnings]);return ['id'=>$id,'message'=>'Test setup saved.','warnings'=>$warnings];});}
 public function list(Request $r,array $d){[$sid,$m]=$this->exam->context($r);$sections=$this->exam->sections($r)->pluck('s.id');$q=DB::table('tests as t')->join('subjects as u','u.id','=','t.subject_id')->join('sections as s','s.id','=','t.section_id')->join('classes as c','c.id','=','s.class_id')->join('campuses as p','p.id','=','s.campus_id')->where('t.school_id',$sid)->whereIn('t.section_id',$sections);if(!$this->exam->can($r,'tests.publish'))$q->whereExists(fn($q)=>$q->selectRaw('1')->from('teacher_assignments as a')->join('staff_profiles as f','f.id','=','a.staff_profile_id')->whereColumn('a.school_id','t.school_id')->whereColumn('a.section_id','t.section_id')->where('f.membership_id',$m->id)->where('f.status','active')->where(fn($q)=>$q->whereColumn('a.subject_id','t.subject_id')->orWhere('a.is_class_teacher',true)));if(!empty($d['section_id']))$q->where('t.section_id',$d['section_id']);if(!empty($d['exam_cycle_id']))$q->where('t.exam_cycle_id',$d['exam_cycle_id']);return $q->orderByDesc('t.test_date')->orderByDesc('t.id')->paginate(20,['t.*','u.name as subject_name','s.name as section_name','c.name as class_name','p.name as campus_name']);}
 public function marks(Request $r,int $id):array{[$t,$s]=$this->exam->test($r,$id);[$sid,$m]=$this->exam->context($r);$roster=$this->exam->roster($sid,$s->id,$t->test_date);$rows=DB::table('test_results')->where('school_id',$sid)->where('test_id',$id)->get();$map=$rows->keyBy('enrollment_id');foreach($roster as $student){$row=$map->get($student->enrollment_id);$student->result_id=$row?->id;$student->marks=$row?->marks;$student->status=$row?->status??'pending';$student->remarks=$row?->remarks;}$canWrite=$this->exam->can($r,'tests.enter_marks')&&($this->exam->can($r,'tests.publish')||$this->exam->assignments($m)->where('a.section_id',$s->id)->where('a.subject_id',$t->subject_id)->exists());$resultIds=$rows->pluck('id');return ['test'=>$t,'section'=>$s,'subject'=>DB::table('subjects')->where('school_id',$sid)->where('id',$t->subject_id)->first(['name','code']),'scheme'=>$this->exam->scheme($sid,$t->grading_scheme_id),'roster'=>$roster,'orphan_count'=>$rows->whereNotIn('enrollment_id',$roster->pluck('enrollment_id'))->count(),'can_write'=>$canWrite&&$t->test_date<=now('Asia/Karachi')->toDateString()&&$t->status==='draft'&&$s->session_status==='active'&&$s->campus_status==='active','can_publish'=>$this->exam->can($r,'tests.publish')&&$s->session_status==='active'&&$s->campus_status==='active','paper'=>DB::table('exam_papers')->where('school_id',$sid)->where('test_id',$id)->first(),'reports'=>DB::table('report_snapshots as p')->join('test_results as r','r.id','=','p.test_result_id')->join('enrollments as e','e.id','=','r.enrollment_id')->join('students as s','s.id','=','e.student_id')->where('p.school_id',$sid)->whereIn('p.test_result_id',$resultIds)->orderByDesc('p.revision')->get(['p.id','p.revision','p.published_at','r.enrollment_id','s.first_name','s.last_name','s.admission_no'])];}
 public function change(Request $r,int $id,array $d):array{return DB::transaction(function()use($r,$id,$d){$sid=$this->exam->lock($r);[$t,$s]=$this->exam->test($r,$id);$this->exam->active($s);if($t->lock_version!=$d['lock_version'])$this->exam->fail('A newer marks/setup change exists. Reload before saving.');$action=$d['action'];$reason=trim($d['reason']??'');$publisher=$this->exam->can($r,'tests.publish');if(in_array($action,['return','publish','revise'],true))abort_unless($publisher,403);else $this->exam->subject($r,$s,$t->subject_id,true);if(in_array($action,['return','revise'],true)&&mb_strlen($reason)<5)$this->exam->fail('Enter a review/correction reason of at least five characters.');$before=DB::table('test_results')->where('school_id',$sid)->where('test_id',$id)->orderBy('enrollment_id')->get();$values=['lock_version'=>$t->lock_version+1,'updated_at'=>now()];
  if($action==='revise'){if($t->status!=='published'||!$t->publication_revision)$this->exam->fail('Only a published assessment can start a correction.');$values+=['status'=>'draft','correction_reason'=>$reason];}
  elseif($action==='return'){if($t->status!=='in_review')$this->exam->fail('Only a submitted test can be returned.');$values['status']='draft';}
  else {if($t->test_date>now('Asia/Karachi')->toDateString())$this->exam->fail('Marks cannot be entered or published before the test date.');$roster=$this->exam->roster($sid,$s->id,$t->test_date);if(!$roster->count())$this->exam->fail('No students were enrolled on this test date.');if($before->whereNotIn('enrollment_id',$roster->pluck('enrollment_id'))->isNotEmpty())$this->exam->fail('Saved results conflict with enrollment history. Review the enrollment dates; saved results were retained.');
   if($action==='save'){if($t->status!=='draft')$this->exam->fail('Only a draft test can accept marks.');$rows=collect($d['records']??[]);if($rows->pluck('enrollment_id')->sort()->values()->all()!==$roster->pluck('enrollment_id')->map(fn($x)=>(int)$x)->sort()->values()->all())$this->exam->fail('Save the complete displayed roster. Rows from other sections/dates are not accepted.');foreach($rows as $row){$marks=$row['marks']??null;if($row['status']==='present'){if($marks===null||$marks==='')$this->exam->fail('Present students need marks; zero is allowed.');if($this->exam->cents($marks)>$this->exam->cents($t->max_marks))$this->exam->fail('Marks cannot exceed the test maximum.');}elseif($marks!==null&&$marks!=='')$this->exam->fail('Absent, exempt and pending rows must not contain marks.');DB::table('test_results')->updateOrInsert(['school_id'=>$sid,'test_id'=>$id,'enrollment_id'=>$row['enrollment_id']],['marks'=>$row['status']==='present'?$marks:null,'status'=>$row['status'],'remarks'=>trim($row['remarks']??'')?:null,'revision'=>$t->publication_revision+1,'updated_at'=>now()]);}}
   else {if(($action==='submit'&&$t->status!=='draft')||($action==='publish'&&$t->status!=='in_review'))$this->exam->fail('Save a draft, submit it for review, then publish.');if($before->count()!==$roster->count()||$before->contains('status','pending'))$this->exam->fail('Every enrolled student needs present, absent or exempt status before submission.');foreach($before as $row)if($row->status==='present'&&$this->exam->cents($row->marks)>$this->exam->cents($t->max_marks))$this->exam->fail('Saved marks exceed the maximum.');$values['status']=$action==='submit'?'in_review':'published';if($action==='publish'){$revision=$t->publication_revision+1;$g=$this->exam->scheme($sid,$t->grading_scheme_id);$school=DB::table('schools')->where('id',$sid)->first();$subject=DB::table('subjects')->where('school_id',$sid)->where('id',$t->subject_id)->value('name');$ranks=$this->ranks($before->where('status','present')->mapWithKeys(fn($row)=>[$row->enrollment_id=>$this->exam->cents($row->marks)])->all(),$g->tie_policy);$map=$roster->keyBy('enrollment_id');foreach($before as $row){$student=$map[$row->enrollment_id];$present=$row->status==='present';$pct=$present?$this->exam->percent($this->exam->cents($row->marks),$this->exam->cents($t->max_marks),$g):null;$payload=['kind'=>'test','school_name'=>$school->name,'school_code'=>$school->code,'student'=> (array)$student,'section_label'=>$s->class_name.' · '.$s->name.' · '.$s->campus_name.' · '.$s->session_name,'title'=>$t->title,'date'=>$t->test_date,'subject_name'=>$subject,'status'=>$row->status,'marks'=>$row->marks,'max_marks'=>$t->max_marks,'passing_marks'=>$t->passing_marks,'percent'=>$pct===null?null:$this->exam->number($pct),'grade'=>$pct===null?'—':$this->exam->grade($pct,$g),'outcome'=>$row->status==='exempt'?'Exempt':($present&&$this->exam->cents($row->marks)>=$this->exam->cents($t->passing_marks)?'Pass':'Fail'),'rank'=>$ranks[$row->enrollment_id]??null,'remarks'=>$row->remarks,'revision'=>$revision,'grading'=>['name'=>$g->name,'version'=>$g->version,'rounding'=>$g->rounding_policy,'ties'=>$g->tie_policy],'correction_reason'=>$t->correction_reason];DB::table('report_snapshots')->insert(['school_id'=>$sid,'test_result_id'=>$row->id,'grading_scheme_id'=>$g->id,'revision'=>$revision,'payload'=>json_encode($payload,JSON_UNESCAPED_UNICODE),'published_by'=>$this->exam->access->membership($r)->id,'published_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('test_results')->where('id',$row->id)->update(['revision'=>$revision]);}$values['publication_revision']=$revision;}}
  }
  DB::table('tests')->where('school_id',$sid)->where('id',$id)->update($values);$after=DB::table('test_results')->where('school_id',$sid)->where('test_id',$id)->orderBy('enrollment_id')->get();$this->exam->access->audit($r,'exams.'.$action,'tests',$id,['reason'=>$reason?:null,'before_status'=>$t->status,'after_status'=>$values['status']??$t->status,'before'=>$before->all(),'after'=>$after->all(),'publication_revision'=>$values['publication_revision']??$t->publication_revision]);return ['message'=>match($action){'save'=>'Marks draft saved.','submit'=>'Marks submitted for review.','return'=>'Marks returned for changes.','publish'=>'Results published.','revise'=>'Correction draft opened. Earlier reports remain archived.'}];});}
 public function ranks(array $scores,string $policy):array{if($policy==='none')return [];arsort($scores,SORT_NUMERIC);$ranks=[];$previous=null;$position=0;$dense=0;$rank=0;foreach($scores as $id=>$score){$position++;if($previous===null||$score!==$previous){$dense++;$rank=$policy==='dense'?$dense:$position;}$ranks[$id]=$rank;$previous=$score;}return $ranks;}
}
